const state={config:null,user:null,csrf:null,products:[],cart:{items:[],subtotal:0},category:'Todos',search:'',adminProducts:[],adminOrders:[],quote:null,checkoutKey:null};
const $=s=>document.querySelector(s);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currencyLabel=()=>state.config?.currency==='EUR'?'€':'R$';
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:state.config?.currency||'BRL'}).format((v||0)/100);
const date=v=>new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
const roleNames={admin:'Administrador',customer:'Cliente',inventory:'Estoque',finance:'Financeiro',shipping:'Expedição',support:'Atendimento'};
const statuses={awaiting_payment:'Aguardando pagamento',paid:'Pago',picking:'Em separação',ready:'Pronto para envio',shipped:'Enviado',delivered:'Entregue',expired:'Expirado',cancelled:'Cancelado',refunded:'Estornado',payment_review:'Pagamento em análise',pending:'Pendente',approved:'Aprovado'};
const badge=s=>`<span class="badge ${escape(s)}">${escape(statuses[s]||s)}</span>`;
const colors=['#f0f0f0','#e5e5e5','#fafafa','#d4d4d4','#eeeeee','#ffffff'];
const productVisual=p=>p.images?.length?`<img class="product-photo" src="${escape(p.images[0])}" alt="${escape(p.name)}" loading="lazy">`:`<span class="product-symbol" aria-hidden="true">${escape(p.icon)}</span>`;
const colorClass=c=>`color-${Math.max(1,colors.indexOf(c)+1)}`;
const has=p=>state.user?.permissions.includes(p);
const field=(name,label,value='',type='text',extra='')=>`<label class="field">${escape(label)}<input name="${name}" type="${type}" value="${escape(value)}" ${extra}></label>`;
const empty=(title,description='')=>`<div class="empty"><strong>${escape(title)}</strong>${escape(description)}</div>`;
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000);}
async function api(path,options={}) {
  const response=await fetch(`/api${path}`,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...options.headers},...(options.body?{body:JSON.stringify(options.body)}:{})});
  const result=await response.json(); if(!response.ok) throw new Error(result.error||'Não foi possível concluir.');return result;
}
function dialog(title,content){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${escape(title)}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">×</button></div><div class="dialog-body">${content}</div>`;if(!d.open)d.showModal();}
function closeDialog(){ $('#dialog').close(); }
const catalogMode=()=>state.config?.mode==='catalog';
const demoBanner=()=>catalogMode()?'<div class="demo">LOJA EM PREPARAÇÃO · Conheça os produtos. Compras disponíveis em breve.</div>':state.config.mode==='demo'?'<div class="demo">AMBIENTE DE DEMONSTRAÇÃO · Pagamentos e fretes simulados, sem cobrança real.</div>':'';
const brand=()=>`<a class="brand" href="#store"><span class="brand-logo"><img src="/edg-logo.png" alt="EDG"></span></a>`;
function storeShell(content) {
  const count=state.cart.items.reduce((s,p)=>s+p.quantity,0);
  return `${demoBanner()}<header class="topbar">${brand()}<nav class="toplinks"><a href="#store">Início</a><a href="#catalog">Coleção</a><a href="#orders">Meus pedidos</a>${has('dashboard')?'<a href="#admin">Gestão</a>':''}</nav><div class="topactions">${state.user?`<button class="btn small" data-action="account">${escape(state.user.name.split(' ')[0])} · Minha conta</button>`:'<button class="btn small" data-action="login">Entrar</button>'}<a class="btn small" href="#cart">Sacola <span class="cart-count">${count}</span></a></div></header><main class="store-main">${content}<footer class="footer"><div>${brand()}</div><nav aria-label="Links do rodapé"><a href="#catalog">Coleção</a><a href="#orders">Meus pedidos</a><a href="#cart">Sacola</a></nav><span>© ${new Date().getFullYear()} EDG</span></footer></main>`;
}
function productCards(){
  const items=state.products.filter(p=>(state.category==='Todos'||p.category===state.category)&&`${p.name} ${p.sku}`.toLowerCase().includes(state.search.toLowerCase()));
  return items.length?items.map(p=>`<article class="product"><button class="product-visual ${colorClass(p.color)}" data-action="product" data-id="${p.id}" aria-label="Ver ${escape(p.name)}"><span class="chip">${p.available?'Disponível':'Esgotado'}</span>${productVisual(p)}</button><div class="product-info"><span class="muted">${escape(p.category)}</span><h3>${escape(p.name)}</h3><div class="product-bottom"><span class="product-price">${money(p.price)}</span><button class="product-add" data-action="add" data-id="${p.id}" ${!p.available||catalogMode()?'disabled':''} aria-label="Adicionar ${escape(p.name)}">+</button></div></div></article>`).join(''):empty('Nenhum produto encontrado','Altere a busca ou a categoria.');
}
function storePage(){return storeShell(`<section class="campaign"><div class="campaign-copy"><span class="eyebrow">EDG / Independent spirit</span><h1>SEU ESTILO.<br>SUAS REGRAS.</h1><p>Atitude em cada escolha. Explore a seleção EDG.</p><a class="btn primary" href="#catalog">Explorar coleção ↗</a><span class="campaign-caption">IDENTIDADE PRÓPRIA. TODOS OS DIAS.</span></div><div class="campaign-art" aria-hidden="true"><span class="campaign-index">EST. EDG / 001</span><div class="campaign-logo"><img src="/edg-logo.png" alt=""></div><span class="campaign-art-label">INDEPENDENT<br>BY NATURE.</span></div></section><div class="brand-strip" aria-hidden="true"><span>EDG ORIGINALS</span><span>✳</span><span>SEM RÓTULOS</span><span>✳</span><span>IDENTIDADE PRÓPRIA</span><span>✳</span></div><section id="catalog" class="collection-section"><div class="section-head"><div><span class="eyebrow">Explore / A seleção EDG</span><h2>A COLEÇÃO.</h2></div><span class="collection-count">${state.products.length} produtos</span></div><div class="filters">${['Todos',...new Set(state.products.map(p=>p.category))].map(c=>`<button class="filter ${state.category===c?'active':''}" data-action="filter" data-category="${escape(c)}">${escape(c)}</button>`).join('')}<label class="search"><span class="sr-only">Buscar produtos</span><input id="product-search" placeholder="Buscar na coleção…" value="${escape(state.search)}"></label></div><div class="product-grid" id="product-grid">${productCards()}</div></section><section class="category-section"><div class="section-head"><h2>EXPLORE MAIS.</h2><a href="#catalog">Ver tudo ↗</a></div><div class="category-grid">${[...new Set(state.products.map(p=>p.category))].map((c,i)=>`<button class="category-tile" data-action="collection" data-category="${escape(c)}"><span class="eyebrow">EDG / 0${i+1}</span><strong>${escape(c)}</strong><span>Explorar seleção ↗</span></button>`).join('')}</div></section><section class="brand-statement"><span class="eyebrow">O universo EDG</span><h2>MAIS IDENTIDADE.<br>MENOS DO MESMO.</h2><a class="btn" href="#catalog">Encontre sua próxima escolha ↗</a></section>`);}
function cartPage(){if(catalogMode())return storeShell(empty('Compras disponíveis em breve','Estamos preparando a loja. Explore nosso catálogo.')+'<a class="btn" href="#store">Ver produtos</a>');return storeShell(`<div class="page-title"><div><span class="eyebrow">Sua seleção</span><h1>Minha sacola</h1><p>Confira seus produtos e siga para a entrega.</p></div><a class="btn" href="#store">Continuar comprando</a></div>${!state.user?empty('Entre para acessar sua sacola','Crie uma conta ou entre para iniciar sua compra.')+ '<button class="btn primary" data-action="login">Entrar na minha conta</button>':!state.cart.items.length?empty('Sua sacola está vazia','Explore a loja e adicione seus produtos favoritos.'):`<div class="cart-layout"><div class="panel">${state.cart.items.map(p=>`<div class="cart-row"><span class="cart-icon ${colorClass(p.color)}">${escape(p.icon)}</span><div><h3>${escape(p.name)}</h3><p class="muted">${money(p.price)} por unidade</p><div class="quantity"><button data-action="quantity" data-id="${p.id}" data-delta="-1" aria-label="Diminuir quantidade">−</button><span>${p.quantity}</span><button data-action="quantity" data-id="${p.id}" data-delta="1" aria-label="Aumentar quantidade">+</button><button data-action="remove" data-id="${p.id}" aria-label="Remover produto">×</button></div></div><strong class="price">${money(p.price*p.quantity)}</strong></div>`).join('')}</div><aside class="summary"><h2>Resumo da compra</h2><div class="sum-row"><span>Produtos</span><span>${money(state.cart.subtotal)}</span></div><div class="sum-row"><span>Frete</span><span>Calculado no checkout</span></div><div class="sum-row total"><span>Subtotal</span><span>${money(state.cart.subtotal)}</span></div><button class="btn primary" data-action="checkout">Continuar para entrega →</button><p class="form-help">O estoque será reservado ao confirmar o pedido.</p></aside></div>`}`);}
function ordersPage(orders){return storeShell(`<div class="page-title"><div><span class="eyebrow">Tudo sob controle</span><h1>Meus pedidos</h1><p>Acompanhe o pagamento, o preparo e a entrega.</p></div><a class="btn" href="#store">Ir para a loja</a></div>${!state.user?empty('Entre para ver seus pedidos')+'<button class="btn primary" data-action="login">Entrar</button>':!orders.length?empty('Você ainda não tem pedidos','Suas próximas compras aparecerão aqui.'):`<div class="order-cards">${orders.map(o=>`<article class="order-card"><div class="order-meta"><h3>Pedido #${o.number}</h3><p>${date(o.created_at)} · ${o.items.reduce((s,p)=>s+p.quantity,0)} item(ns)</p></div>${badge(o.status)}<strong>${money(o.total)}</strong><button class="btn small" data-action="order" data-id="${o.id}">Ver pedido ↗</button></article>`).join('')}</div>`}`);}
const navItems=[['admin','Visão geral','◉','dashboard'],['products','Produtos','▦','catalog'],['stock','Estoque','▤','stock'],['sales','Pedidos','▣','orders'],['finance','Financeiro','↗','finance'],['shipping','Expedição','▱','shipping'],['users','Usuários','♧','users'],['coupons','Cupons','◇','coupons'],['invoices','Notas fiscais','▧','invoices'],['emails','E-mails','✉','users'],['audit','Atividades','◷','audit']];
function adminShell(page,content){return `${demoBanner()}<div class="admin-shell"><aside class="sidebar">${brand()}<p class="eyebrow">Gestão da operação</p><nav class="side-nav">${navItems.filter(n=>has(n[3])).map(([id,label,icon])=>`<a href="#${id}" class="${page===id?'active':''}"><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#store">↗ &nbsp; Acessar loja</a><button class="btn small" data-action="logout">Sair da conta</button></div></aside><div><header class="admin-top"><p>EDG / ${escape(navItems.find(n=>n[0]===page)?.[1]||'Gestão')}</p><div class="stack"><a class="btn small" href="#store">Ver loja ↗</a><button class="btn small" data-action="account"><span class="user-pill"><b class="avatar">${escape(state.user.name.slice(0,2).toUpperCase())}</b><span>${escape(state.user.name)}<br><small class="role-label">${roleNames[state.user.role]}</small></span></span></button></div></header><main class="admin-main">${content}</main></div></div>`;}
const title=(heading,description,action='')=>`<div class="page-title"><div><h1>${heading}</h1><p>${description}</p></div>${action}</div>`;
function orderTable(orders,shipping=false){return !orders.length?empty('Nenhum pedido por aqui','Os pedidos aparecerão nesta lista.'): `<div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Valor</th><th>${shipping?'Rastreio':'Status'}</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>#${o.number}</strong><small>${o.items.length} produto(s)</small></td><td>${escape(o.customer_name)}<small>${escape(o.customer_email)}</small></td><td>${date(o.created_at)}</td><td>${money(o.total)}</td><td>${shipping?`${escape(o.tracking_code||'Não informado')}<small>${statuses[o.status]}</small>`:badge(o.status)}</td><td><button class="btn small" data-action="admin-order" data-id="${o.id}">Detalhes ↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function dashboardPage(data){const m=data.metrics,financial=has('finance');const metrics=financial?[['Receita líquida',money(m.net_revenue),'Recebimentos − estornos − despesas'],['Pedidos',m.orders,'Total de pedidos na loja'],['A expedir',m.to_ship,'Pagos, em separação ou prontos'],['Estoque baixo',m.low_stock,'Produtos no limite de reposição']]:[['Pedidos',m.orders,'Total de pedidos na loja'],['A expedir',m.to_ship,'Próximas entregas'],['Produtos',m.products,'Produtos ativos'],['Estoque baixo',m.low_stock,'Produtos no limite de reposição']];const max=Math.max(1,...data.revenue.map(r=>Math.abs(r.amount)));return adminShell('admin',`${title(`Olá, ${escape(state.user.name.split(' ')[0])}.`,'Sua operação em uma visão clara, do pedido à entrega.','<button class="btn" data-action="refresh">↻ Atualizar</button>')}<div class="metrics">${metrics.map(([label,value,note])=>`<article class="metric"><div class="label">${label}<span>↗</span></div><strong>${value}</strong><p>${note}</p></article>`).join('')}</div><section class="panel"><div class="panel-title"><div><h2>Pedidos recentes</h2><p>Acompanhe as últimas movimentações da loja</p></div><a class="btn small" href="#sales">Ver todos →</a></div>${orderTable(data.recent_orders)}</section><div class="dashboard-bottom"><section class="panel"><div class="panel-title"><div><h2>${financial?'Movimento financeiro':'Sua operação conectada'}</h2><p>${financial?'Saldo diário dos últimos dias com lançamentos':'Loja, estoque e entrega no mesmo fluxo'}</p></div></div>${financial&&data.revenue.length?`<div class="bar-chart" role="img" aria-label="Saldo diário: ${escape(data.revenue.slice().reverse().map(r=>`${r.day}: ${money(r.amount)}`).join('; '))}">${data.revenue.slice().reverse().map(r=>`<div class="bar h-${Math.max(1,Math.round(Math.abs(r.amount)/max*10))}" title="${r.day}: ${money(r.amount)}"></div>`).join('')}</div><p class="chart-note">Altura representa o valor absoluto. Valores e sinais disponíveis ao passar o mouse.</p>`:empty('Pronto para começar','As vendas confirmadas alimentarão os indicadores.')}</section><section class="panel"><div class="panel-title"><div><h2>Hora de repor</h2><p>Produtos que merecem atenção</p></div><span class="chip">${data.alerts.length}</span></div>${data.alerts.length?`<div class="alert-list">${data.alerts.slice(0,5).map(p=>`<div class="alert-item"><span>${escape(p.name)}</span><span class="badge expired">${p.available} un.</span></div>`).join('')}</div>`:empty('Estoque em dia','Nenhum alerta de reposição.')}</section></div>`);}
function productsPage(products,stock=false){return adminShell(stock?'stock':'products',`${title(stock?'Estoque':'Produtos',stock?'Saldo físico, reservas e movimentações rastreáveis.':'Organize o catálogo e os preços da sua loja.',stock?'':'<button class="btn primary" data-action="categories">Categorias</button><button class="btn primary" data-action="new-product">+ Novo produto</button>')}${stock?'<div class="note">Disponível = estoque físico − reservas. Ajustes exigem motivo e não podem consumir unidades reservadas.</div>':''}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Produto / SKU</th>${stock?'<th>Físico</th><th>Reservado</th><th>Disponível</th>':'<th>Categoria</th><th>Preço</th><th>Situação</th>'}<th></th></tr></thead><tbody>${products.map(p=>`<tr><td><strong>${escape(p.icon)} &nbsp; ${escape(p.name)}</strong><small>${escape(p.sku)}${p.size?` · ${escape(p.size)}`:''}</small></td>${stock?`<td>${p.stock}</td><td>${p.reserved}</td><td>${p.available<=p.low_stock?`<span class="badge expired">${p.available} · Repor</span>`:p.available}</td>`:`<td>${escape(p.category)}</td><td>${money(p.price)}<small>Custo ${money(p.cost)}</small></td><td>${p.active?'<span class="badge approved">Ativo</span>':'<span class="badge cancelled">Inativo</span>'}</td>`}<td><button class="btn small" data-action="${stock?'adjust-stock':'edit-product'}" data-id="${p.id}">${stock?'Ajustar estoque':'Editar'}</button></td></tr>`).join('')}</tbody></table></div>${!products.length?empty('Cadastre seu primeiro produto'):''}</section>${stock?'<section class="panel"><div class="panel-title"><h2>Últimas movimentações</h2></div><div id="movements"></div></section>':''}`);}
function financePage(ledger,data){const income=ledger.filter(l=>l.type==='income').reduce((s,l)=>s+l.amount,0),refunds=ledger.filter(l=>l.type==='refund').reduce((s,l)=>s+l.amount,0),expenses=ledger.filter(l=>l.type==='expense').reduce((s,l)=>s+l.amount,0);return adminShell('finance',`${title('Financeiro','Recebimentos confirmados, despesas e estornos.','<button class="btn primary" data-action="expense">+ Registrar despesa</button>')}<div class="metrics">${[['Saldo líquido',money(data.metrics.net_revenue),'Total de todo o histórico'],['Recebimentos',money(income),'Últimos 500 lançamentos'],['Estornos',money(-refunds),'Últimos 500 lançamentos'],['Despesas',money(-expenses),'Últimos 500 lançamentos']].map(([a,b,c])=>`<article class="metric"><div class="label">${a}</div><strong>${b}</strong><p>${c}</p></article>`).join('')}</div><div class="note">Receita líquida é o saldo de recebimentos, estornos e despesas lançadas. Taxas do gateway e custos de frete devem ser registrados como despesas. Este painel não calcula lucro contábil.</div><section class="panel"><div class="panel-title"><h2>Lançamentos</h2><button class="btn small" data-action="export-finance">Exportar CSV ↓</button></div>${ledger.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Valor</th></tr></thead><tbody>${ledger.map(l=>`<tr><td>${date(l.created_at)}</td><td>${escape(l.description)}</td><td>${{income:'Recebimento',refund:'Estorno',expense:'Despesa'}[l.type]}</td><td class="${l.amount>0?'ledger-positive':'ledger-negative'}"><strong>${money(l.amount)}</strong></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum lançamento ainda')}</section>`);}
function usersPage(users){return adminShell('users',`${title('Usuários e acessos','Cada pessoa com as permissões necessárias para sua função.','<button class="btn primary" data-action="new-user">+ Novo usuário</button>')}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Situação</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${escape(u.name)}</strong></td><td>${escape(u.email)}</td><td>${roleNames[u.role]}</td><td>${u.active?'<span class="badge approved">Ativo</span>':'<span class="badge cancelled">Bloqueado</span>'}</td><td>${u.id!==state.user.id?`<button class="btn small" data-action="edit-user" data-id="${u.id}">Permissões</button>`:'<span class="muted">Seu acesso</span>'}</td></tr>`).join('')}</tbody></table></div></section>`);}
let renderVersion=0;
async function render(){const version=++renderVersion;let page=location.hash.slice(1)||'store';if(page==='catalog')page='store';const needsLogin=!state.user&&navItems.some(([id])=>id===page);if(needsLogin)page='store';try{
  let html;
  if(page.startsWith('reset-password/')){html=storeShell('<div class="password-page"><h1>Crie uma nova senha</h1><p class="muted">O link é temporário e pode ser utilizado uma vez.</p><form id="reset-form" data-token="'+escape(page.split('/')[1])+'">'+field('password','Nova senha','','password','required minlength="12" maxlength="128" autocomplete="new-password"')+'<button class="btn primary" type="submit">Salvar nova senha</button></form></div>');}
  else if(['store','cart','orders'].includes(page)) {
    state.products=await api('/products');if(state.user)state.cart=await api('/cart');
    html=page==='store'?storePage():page==='cart'?cartPage():ordersPage(state.user?await api('/orders'):[]);
  } else {
    if(!has('dashboard')) {location.hash='store';if(!state.user)authDialog();return;}
    const permission=navItems.find(n=>n[0]===page)?.[3];if(!permission || !has(permission)){location.hash='admin';return;}
    if(page==='admin')html=dashboardPage(await api('/admin/dashboard'));
    if(['products','stock'].includes(page)){state.adminProducts=await api('/admin/products');if(page==='products')state.categories=await api('/admin/categories');html=productsPage(state.adminProducts,page==='stock');}
    if(['sales','shipping'].includes(page)){state.adminOrders=await api('/admin/orders');let orders=state.adminOrders;if(page==='shipping')orders=orders.filter(o=>['paid','picking','ready','shipped','delivered'].includes(o.status));html=adminShell(page,`${title(page==='shipping'?'Expedição e entregas':'Pedidos',page==='shipping'?'Prepare, envie e acompanhe cada entrega.':'Uma linha do tempo para cada venda.','<button class="btn" data-action="refresh">↻ Atualizar</button>')}<div class="filters">${['Todos',...(page==='shipping'?['paid','picking','ready','shipped','delivered']:['awaiting_payment','paid','shipped','cancelled','payment_review'])].map(s=>`<button class="filter ${s==='Todos'?'active':''}" data-action="order-filter" data-status="${s}" data-shipping="${page==='shipping'}">${statuses[s]||s}</button>`).join('')}</div><section class="panel" id="orders-table">${orderTable(orders,page==='shipping')}</section>`);}
    if(page==='finance'){state.ledger=await api('/admin/finance');html=financePage(state.ledger,await api('/admin/dashboard'));}
    if(page==='coupons'){state.coupons=await api('/admin/coupons');html=couponsPage(state.coupons);}
    if(page==='invoices'){state.invoices=await api('/admin/invoices');html=invoicesPage(state.invoices);}
    if(page==='emails'){html=emailsPage(await api('/admin/emails'));}
    if(page==='users'){state.users=await api('/admin/users');html=usersPage(state.users);}
    if(page==='audit'){const logs=await api('/admin/audit');html=adminShell(page,`${title('Atividades','Histórico das alterações feitas pela equipe.')}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Referência</th></tr></thead><tbody>${logs.map(l=>`<tr><td>${date(l.created_at)}</td><td>${escape(l.actor_name||'Sistema')}</td><td>${escape(l.action)}</td><td>${escape(l.entity_id||'—')}</td></tr>`).join('')}</tbody></table></div></section>`);}
  }
  if(version!==renderVersion)return;$('#app').innerHTML=html;if(needsLogin)authDialog();
  if(page==='stock'){const rows=await api('/admin/movements');if(version!==renderVersion)return;$('#movements').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Produto</th><th>Variação</th><th>Motivo</th><th>Responsável</th><th>Data</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escape(r.product_name)}</td><td>${r.quantity>0?'+':''}${r.quantity}</td><td>${escape(r.reason)}</td><td>${escape(r.actor_name||'Sistema')}</td><td>${date(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma movimentação');}
  if(location.hash==='#catalog')$('#catalog')?.scrollIntoView({behavior:'smooth'});
}catch(e){toast(e.message,true);if(!$('#app').children.length)$('#app').innerHTML=empty('Não foi possível carregar','Atualize a página para tentar novamente.');}}
function authDialog(register=false){dialog(register?'Crie sua conta':'Bem-vindo de volta',`<p class="muted">${register?'Cadastre-se para comprar e acompanhar seus pedidos.':'Entre para acessar sua loja e seus pedidos.'}</p><form id="auth-form" data-register="${register}">${register?field('name','Nome completo','','text','required minlength="2" autocomplete="name"'):''}${field('email','E-mail','','email','required autocomplete="email"')}${field('password','Senha','','password',`required ${register?'minlength="12"':''} maxlength="128" autocomplete="${register?'new-password':'current-password'}"`)}${register?'<p class="form-help">Use uma senha exclusiva com pelo menos 12 caracteres.</p>':''}<div class="form-actions"><button class="btn primary" type="submit">${register?'Criar conta':'Entrar'}</button></div></form>${!register?'<div class="switch-auth"><button data-action="forgot">Esqueci minha senha</button></div>':''}<div class="switch-auth">${register?'Já tem conta?':'Ainda não tem conta?'}<button data-action="${register?'login':'register'}">${register?'Entrar':'Criar minha conta'}</button></div>`);}
function accountDialog(){dialog('Minha conta',`<h3>${escape(state.user.name)}</h3><p class="muted">${escape(state.user.email)} · ${roleNames[state.user.role]}</p><div class="stack form-actions">${has('dashboard')?'<a class="btn" href="#admin" data-action="close">Acessar gestão</a>':''}<button class="btn" data-action="password">Alterar senha</button><button class="btn danger" data-action="logout">Sair</button></div>`);}
function checkoutDialog(){if(catalogMode())return toast('Compras disponíveis em breve.');state.quote=null;state.coupon=null;state.checkoutKey=crypto.randomUUID();dialog('Entrega e pagamento',`<form id="checkout-form"><div class="form-grid">${field('name','Nome do destinatário',state.user.name,'text','required')}${field('phone','Telefone','','tel','required')}${field('document','CPF / CNPJ','','text','required')}${field('postal_code','CEP','','text','required maxlength="9"')}${field('street','Rua / Avenida','','text','required')}${field('number','Número','','text','required')}${field('district','Bairro','','text','required')}${field('complement','Complemento')}${field('city','Cidade','','text','required')}${field('state','UF','','text','required minlength="2" maxlength="2" pattern="[A-Z]{2}"')}</div><div class="coupon-entry">${field('coupon','Cupom de desconto (opcional)')}<button class="btn" type="button" data-action="apply-coupon">Aplicar cupom</button></div><div id="coupon-summary"></div><button type="button" class="btn form-actions" data-action="quote">Calcular frete</button><div id="quote-results" class="quote-results"></div><div class="checkout-total"><span>Produtos</span><span id="checkout-products-total">${money(state.cart.subtotal)}</span></div><p class="form-help">${state.config.mode==='demo'?'Demonstração: você poderá simular o pagamento no pedido.':'Você será direcionado ao Mercado Pago para escolher a forma de pagamento.'}</p><div class="form-actions"><button class="btn primary" type="submit" id="place-order" disabled>Confirmar pedido →</button></div></form>`);}
function productDialog(p){dialog(p.name,`<div class="product-visual ${colorClass(p.color)}">${productVisual(p)}</div>${p.images?.length>1?`<div class="photo-gallery">${p.images.map(url=>`<button data-action="photo-main" data-url="${escape(url)}"><img src="${escape(url)}" alt="Foto de ${escape(p.name)}"></button>`).join('')}</div>`:''}<p class="muted form-help">${escape(p.category)}${p.size?` · Tamanho: ${escape(p.size)}`:''} · ${escape(p.sku)}</p><p>${escape(p.description)}</p><div class="detail-heading form-actions"><strong>${money(p.price)}</strong><button class="btn primary" data-action="add" data-id="${p.id}" ${!p.available||catalogMode()?'disabled':''}>${catalogMode()?'Disponível em breve':p.available?'Adicionar à sacola':'Esgotado'}</button></div>`);}
function categoriesDialog(){dialog('Categorias',`<form id="category-form">${field('name','Nova categoria','','text','required maxlength="80"')}<div class="form-actions"><button class="btn primary">Adicionar categoria</button></div></form><p class="form-help">Renomear uma categoria atualiza todos os produtos associados.</p>${state.categories.map(c=>`<form class="category-edit-form" data-previous="${escape(c.name)}"><div class="form-grid">${field('name','Categoria',c.name,'text','required maxlength="80"')}<div class="form-actions"><button class="btn">Salvar alteração</button></div></div></form>`).join('')}`);}
function sizeField(category,value=''){
  const sizes=state.categories.find(c=>c.name===category)?.sizes||[];
  return sizes.length?`<label class="field">${/shai?pe/i.test(category)?'Largura do shape (polegadas)':'Tamanho'}<select name="size" required><option value="">Selecione o tamanho</option>${sizes.map(size=>`<option value="${escape(size)}" ${value===size?'selected':''}>${escape(size)}</option>`).join('')}</select></label><p class="form-help">Cadastre um SKU por tamanho para controlar o estoque.</p>`:field('size','Tamanho (opcional)',value,'text','maxlength="30"');
}
function productEditor(p={}){state.editPhotoIds=JSON.parse(p.images||'[]');state.uploading=false;dialog(p.id?'Editar produto':'Novo produto',`<form id="product-form" data-id="${p.id||''}"><div class="form-grid">${field('name','Nome',p.name||'','text','required')}${field('sku','SKU',p.sku||'','text','required')}<label class="field">Categoria<select name="category" required><option value="">Selecione uma categoria</option>${state.categories.map(c=>`<option value="${escape(c.name)}" ${p.category===c.name?'selected':''}>${escape(c.name)}</option>`).join('')}</select></label><div id="product-size">${sizeField(p.category||'',p.size||'')}</div>${field('price',`Preço (${currencyLabel()})`,((p.price||0)/100).toFixed(2),'number','required min="0.01" step="0.01"')}${field('cost',`Custo (${currencyLabel()})`,((p.cost||0)/100).toFixed(2),'number','required min="0" step="0.01"')}${field('low_stock','Alerta de estoque',p.low_stock??5,'number','required min="0"')}${field('weight','Peso (kg)',p.weight||0.5,'number','required min="0.001" step="0.001"')}${field('width','Largura (cm)',p.width||20,'number','required min="1" step="0.1"')}${field('height','Altura (cm)',p.height||10,'number','required min="1" step="0.1"')}${field('length','Comprimento (cm)',p.length||25,'number','required min="1" step="0.1"')}${field('icon','Símbolo do produto',p.icon||'◇','text','required maxlength="8"')}<label class="field">Cor<select name="color">${colors.map((c,i)=>`<option value="${c}" ${p.color===c?'selected':''}>Paleta ${i+1}</option>`).join('')}</select></label><div class="field full"><span>Fotos do produto</span><input id="product-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><p class="form-help">Até 8 fotos, com no máximo 5 MB cada. JPEG, PNG ou WebP.</p><div id="photo-preview" class="photo-gallery">${photoPreview()}</div></div>${state.config.currency==='EUR'?'':fiscalEditor(JSON.parse(p.fiscal||'{}'))}<label class="field full">Descrição<textarea name="description" required maxlength="2000">${escape(p.description||'')}</textarea></label><label class="field">Situação<select name="active"><option value="true" ${p.active!==0?'selected':''}>Ativo</option><option value="false" ${p.active===0?'selected':''}>Inativo</option></select></label></div><p class="form-help">O saldo inicial e as reposições são registrados na seção Estoque.</p><div class="form-actions"><button class="btn primary" type="submit">Salvar produto</button></div></form>`);}
function stockDialog(p){dialog(`Ajustar estoque · ${p.name}`,`<p class="muted">Físico: ${p.stock} · Reservado: ${p.reserved} · Disponível: ${p.available}</p><form id="stock-form" data-id="${p.id}">${field('delta','Variação em unidades (ex.: 10 ou −2)','','number','required step="1"')}${field('reason','Motivo do ajuste','','text','required minlength="3"')}<p class="form-help">Use valor positivo para entrada e negativo para saída. Devoluções após entrega devem ser conferidas e lançadas aqui.</p><div class="form-actions"><button class="btn primary" type="submit">Registrar ajuste</button></div></form>`);}
function userDialog(u=null){dialog(u?'Alterar permissões':'Novo usuário',`<form id="user-form" data-id="${u?.id||''}">${!u?field('name','Nome','','text','required')+field('email','E-mail','','email','required')+field('password','Senha inicial','','password','required minlength="12" maxlength="128"'): `<h3>${escape(u.name)}</h3><p class="muted">${escape(u.email)}</p>`}<label class="field">Perfil<select name="role">${Object.entries(roleNames).map(([role,label])=>`<option value="${role}" ${u?.role===role?'selected':''}>${label}</option>`).join('')}</select></label>${u?`<label class="field">Situação<select name="active"><option value="true" ${u.active?'selected':''}>Ativo</option><option value="false" ${!u.active?'selected':''}>Bloqueado</option></select></label>`:'<p class="form-help">O usuário poderá alterar a senha na área Minha conta.</p>'}<div class="form-actions"><button class="btn primary" type="submit">Salvar usuário</button></div></form>`);}
function orderDialog(o,admin=false){state.currentOrder={order:o,admin};const a=o.address;const next={paid:['picking','Iniciar separação'],picking:['ready','Marcar como embalado'],ready:['shipped','Registrar envio'],shipped:['delivered','Confirmar entrega']}[o.status];dialog(`Pedido #${o.number}`,`<div class="detail-heading">${badge(o.status)}<strong>${money(o.total)}</strong></div><p>${escape(o.customer_name)} · ${escape(o.customer_email)}</p><p class="muted">${escape(a.street)}, ${escape(a.number)} ${escape(a.complement)} · ${escape(a.district)}<br>${escape(a.city)} / ${escape(a.state)} · CEP ${escape(a.postal_code)}</p><div class="detail-items">${o.items.map(p=>`<div><span>${p.quantity}× ${escape(p.name)}</span><strong>${money(p.price*p.quantity)}</strong></div>`).join('')}${o.discount?`<div><span>Cupom ${escape(o.coupon_code)}</span><strong>− ${money(o.discount)}</strong></div>`:''}<div><span>Frete · ${escape(o.shipping_service.name)}</span><strong>${money(o.shipping)}</strong></div></div>${o.tracking_code?`<p><b>Rastreio:</b> ${escape(o.tracking_code)} ${o.tracking_url?`<a class="btn small" href="${escape(o.tracking_url)}" target="_blank" rel="noopener noreferrer">Acompanhar ↗</a>`:''}</p>`:''}${o.status==='awaiting_payment'?`<p class="form-help">Reserva válida até ${date(o.reserved_until)}.</p>`:''}${o.refunded?`<p class="danger-note">Estornado: ${money(o.refunded)}</p>`:''}${invoiceSummary(o.invoice)}<div class="timeline">${o.events.map(e=>`<div><p>${escape(e.message)}</p><small>${date(e.created_at)}</small></div>`).join('')}</div><div class="detail-actions">${admin&&has('invoices')?`<button class="btn" data-action="invoice" data-id="${o.id}">${o.invoice?'Gerenciar NF-e':'Emitir NF-e'}</button>`:''}${!admin&&o.status==='awaiting_payment'?`<button class="btn primary" data-action="${state.config.mode==='demo'?'demo-pay':'pay'}" data-id="${o.id}">${state.config.mode==='demo'?'Simular pagamento aprovado':'Pagar no Mercado Pago ↗'}</button><button class="btn danger" data-action="cancel-order" data-id="${o.id}">Cancelar pedido</button>`:''}${admin&&has('shipping')&&next&&o.refunded===0?`<button class="btn primary" data-action="next-status" data-id="${o.id}" data-status="${next[0]}">${next[1]}</button>`:''}${admin&&has('finance')&&o.payment_status==='approved'?`<button class="btn danger" data-action="refund" data-id="${o.id}">Estornar pagamento</button>`:''}${admin&&has('shipping')&&o.status==='awaiting_payment'?`<button class="btn danger" data-action="admin-cancel" data-id="${o.id}">Cancelar pedido</button>`:''}${admin&&has('shipping')&&state.config.mode==='live'&&['paid','picking','ready'].includes(o.status)&&!o.refunded?`<button class="btn" data-action="label" data-id="${o.id}">${o.label_id?'Gerenciar etiqueta':'Criar etiqueta'}</button>`:''}${admin&&has('shipping')&&o.label_id?`<button class="btn" data-action="tracking-sync" data-id="${o.id}">Consultar transportadora</button>`:''}${admin&&o.label_url?`<a class="btn" href="${escape(o.label_url)}" target="_blank" rel="noopener noreferrer">Imprimir etiqueta ↗</a>`:''}</div>`);}
async function afterOrderAction(o,admin){orderDialog(o,admin);await render();}
document.addEventListener('input',e=>{if(e.target.id==='product-search'){state.search=e.target.value;$('#product-grid').innerHTML=productCards();}if(e.target.form?.id==='checkout-form'&&e.target.name==='coupon'){state.coupon=null;$('#coupon-summary').textContent='';$('#checkout-products-total').textContent=money(state.cart.subtotal);}
if(e.target.form?.id==='checkout-form'&&e.target.name==='postal_code'){state.quote=null;$('#quote-results').innerHTML='';$('#place-order').disabled=true;}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;el.disabled=true;try{
  if(action==='close')closeDialog();
  if(action==='forgot')forgotDialog();
  if(action==='photo-main'){$('#dialog .product-photo').src=el.dataset.url;}
  if(action==='remove-photo'){state.editPhotoIds.splice(Number(el.dataset.index),1);$('#photo-preview').innerHTML=photoPreview();}
  if(action==='new-coupon')couponDialog();
  if(action==='toggle-coupon'){await api(`/admin/coupons/${el.dataset.code}`,{method:'PATCH',body:{active:el.dataset.active==='true'}});await render();}
  if(action==='apply-coupon'){const code=$('#checkout-form').elements.coupon.value.trim();state.coupon=code?await api('/coupons/check',{method:'POST',body:{code}}):null;$('#coupon-summary').textContent=state.coupon?`Desconto: ${money(state.coupon.discount)} · ${state.coupon.code}`:'';$('#checkout-products-total').textContent=money(state.cart.subtotal-(state.coupon?.discount||0));}
  if(action==='invoice'){const order=state.adminOrders.find(o=>o.id===id)||await api('/admin/orders').then(rows=>rows.find(o=>o.id===id));const rows=await api('/admin/invoices');const row=rows.find(i=>i.order_id===id);invoiceDialog(order,row);}
  if(action==='invoice-issue'){state.invoiceOrderId=id;const preview=await api(`/admin/orders/${id}/invoice-preview`);invoiceIssueDialog(id,preview);}
  if(action==='invoice-consult'){const row=await api(`/admin/orders/${id}/invoice`,{method:'POST',body:{action:'consult'}});invoiceDialog(state.invoiceOrder,row);await render();}
  if(action==='invoice-cancel')dialog('Cancelar NF-e',`<p>O cancelamento será solicitado ao provedor fiscal. Estornar o pagamento é uma operação separada.</p><form id="invoice-cancel-form" data-id="${id}">${field('reason','Justificativa','','text','required minlength="15" maxlength="255"')}<div class="form-actions"><button class="btn danger" type="submit">Confirmar cancelamento fiscal</button></div></form>`);
  if(action==='login')authDialog();if(action==='register')authDialog(true);if(action==='account')accountDialog();
  if(action==='collection'){state.category=el.dataset.category;location.hash='catalog';await render();document.querySelector('#catalog')?.scrollIntoView();return;}
  if(action==='logout'){await api('/auth/logout',{method:'POST'});state.user=null;state.csrf=null;state.cart={items:[],subtotal:0};closeDialog();location.hash='store';await render();}
  if(action==='password')dialog('Alterar senha',`<form id="password-form">${field('current_password','Senha atual','','password','required autocomplete="current-password"')}${field('password','Nova senha','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="form-help">Você precisará entrar novamente após salvar.</p><div class="form-actions"><button class="btn primary">Salvar senha</button></div></form>`);
  if(action==='categories')categoriesDialog();
  if(action==='filter'){state.category=el.dataset.category;await render();}
  if(action==='product')productDialog(state.products.find(p=>p.id===id));
  if(action==='add'){if(!state.user){authDialog();return;}const p=state.cart.items.find(p=>p.id===id);state.cart=await api(`/cart/${id}`,{method:'PUT',body:{quantity:(p?.quantity||0)+1}});toast('Produto adicionado à sacola.');closeDialog();await render();}
  if(['quantity','remove'].includes(action)){const p=state.cart.items.find(p=>p.id===id);state.cart=await api(`/cart/${id}`,{method:'PUT',body:{quantity:action==='remove'?0:p.quantity+Number(el.dataset.delta)}});await render();}
  if(action==='checkout')checkoutDialog();
  if(action==='quote'){const form=$('#checkout-form');const cep=form.elements.postal_code.value;state.quote=await api('/shipping/quote',{method:'POST',body:{postal_code:cep}});$('#quote-results').innerHTML=state.quote.options.map((q,i)=>`<label class="shipping-choice"><input type="radio" name="service_id" value="${escape(q.id)}" ${i===0?'checked':''}><span>${escape(q.name)}<br><small class="muted">Estimativa de ${escape(q.days)} dias úteis</small></span><strong>${money(q.price)}</strong></label>`).join('');$('#place-order').disabled=false;}
  if(action==='order')orderDialog(await api(`/orders/${id}`));
  if(action==='admin-order')orderDialog(state.adminOrders.find(o=>o.id===id)||await api('/admin/orders').then(rows=>rows.find(o=>o.id===id)),true);
  if(action==='demo-pay')await afterOrderAction(await api(`/orders/${id}/demo-pay`,{method:'POST'}),false);
  if(action==='pay'){const o=await api(`/orders/${id}/payment`,{method:'POST'});if(o.payment_url)location.assign(o.payment_url);}
  if(action==='cancel-order'){const o=await api(`/orders/${id}/cancel`,{method:'POST'});await afterOrderAction(o,false);}
  if(action==='admin-cancel')await afterOrderAction(await api(`/admin/orders/${id}/cancel`,{method:'POST'}),true);
  if(action==='next-status'){if(el.dataset.status==='shipped')dialog('Registrar envio',`<form id="shipping-form" data-id="${id}">${field('tracking_code','Código de rastreio','','text','required minlength="3"')}${field('tracking_url','Link de acompanhamento (opcional)','','url')}<div class="form-actions"><button class="btn primary">Confirmar envio</button></div></form>`);else await afterOrderAction(await api(`/admin/orders/${id}/status`,{method:'POST',body:{status:el.dataset.status}}),true);}
  if(action==='refund')dialog('Estornar pagamento',`<p>Confirma o estorno integral deste pedido? ${state.config.mode==='live'?'Esta ação solicita a devolução real ao Mercado Pago.':'Este estorno será simulado.'}</p><p class="form-help">O estoque retorna automaticamente apenas antes da expedição. Para mercadoria já enviada, confira a devolução e registre a entrada em Estoque.</p><form id="refund-form" data-id="${id}"><div class="form-actions"><button type="button" class="btn" data-action="close">Voltar</button><button class="btn danger">Confirmar estorno integral</button></div></form>`);
  if(action==='label'){const o=state.currentOrder.order;dialog('Etiqueta de envio',o.label_id?`<p>Etiqueta: ${escape(o.label_id)}</p><p class="form-help">Comprar frete utiliza o saldo da conta Melhor Envio. Se houver erro ou resposta incerta, confira o painel antes de repetir.</p><div class="form-actions"><button class="btn" data-action="label-buy-confirm" data-id="${id}">Comprar frete</button><button class="btn primary" data-action="label-print" data-id="${id}">Gerar e imprimir</button></div>`:`<form id="label-form" data-id="${id}">${field('invoice_key','Chave da NF-e (44 dígitos)','','text','required pattern="[0-9]{44}" maxlength="44"')}<p class="form-help">A NF-e deve ser emitida no seu sistema fiscal. Este sistema não emite notas.</p><div class="form-actions"><button class="btn primary">Criar etiqueta no Melhor Envio</button></div></form>`);}
  if(action==='label-buy-confirm')dialog('Confirmar compra do frete',`<p>Esta ação utiliza o saldo da sua conta Melhor Envio para comprar o frete.</p><form id="label-buy-form" data-id="${id}"><div class="form-actions"><button class="btn primary">Confirmar compra</button></div></form>`);
  if(action==='label-print')await afterOrderAction(await api(`/admin/orders/${id}/label`,{method:'POST',body:{action:'print'}}),true);
  if(action==='tracking-sync'){const result=await api(`/admin/orders/${id}/tracking`,{method:'POST'});await afterOrderAction(result.order,true);toast(result.tracking.label);}
  if(action==='new-product')productEditor();if(action==='edit-product')productEditor(state.adminProducts.find(p=>p.id===id));if(action==='adjust-stock')stockDialog(state.adminProducts.find(p=>p.id===id));
  if(action==='new-user')userDialog();if(action==='edit-user')userDialog(state.users.find(u=>u.id===id));
  if(action==='expense'){state.expenseKey=crypto.randomUUID();dialog('Registrar despesa',`<form id="expense-form">${field('description','Descrição','','text','required minlength="3"')}${field('amount',`Valor (${currencyLabel()})`,'','number','required min="0.01" step="0.01"')}<div class="form-actions"><button class="btn primary">Registrar despesa</button></div></form>`);}
  if(action==='export-finance'){const cell=v=>`"${String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")}"`;const csv=`\uFEFFData;Descrição;Tipo;Valor (${currencyLabel()})\n`+state.ledger.map(r=>[r.created_at,r.description,r.type,(r.amount/100).toFixed(2)].map(cell).join(';')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='edg-financeiro.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  if(action==='order-filter'){document.querySelectorAll('.filter').forEach(f=>f.classList.remove('active'));el.classList.add('active');const shipping=el.dataset.shipping==='true',s=el.dataset.status;const rows=state.adminOrders.filter(o=>(s==='Todos'||o.status===s)&&(!shipping||['paid','picking','ready','shipped','delivered'].includes(o.status)));$('#orders-table').innerHTML=orderTable(rows,shipping);}
  if(action==='refresh')await render();
}catch(error){toast(error.message,true);}finally{el.disabled=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,btn=form.querySelector('[type="submit"]')||form.querySelector('button:last-child');if(btn)btn.disabled=true;const data=Object.fromEntries(new FormData(form));try{
  if(form.id==='forgot-form'){const r=await api('/auth/forgot-password',{method:'POST',body:{email:data.email}});dialog('Verifique seu e-mail',`<p>${escape(r.message)}</p>${state.config.mode==='demo'?'<p class="form-help">Na demonstração, o administrador pode consultar a mensagem no painel E-mails.</p>':''}`);}
  if(form.id==='reset-form'){await api('/auth/reset-password',{method:'POST',body:{token:form.dataset.token,password:data.password}});state.user=null;state.csrf=null;state.cart={items:[],subtotal:0};location.hash='store';await render();authDialog();toast('Senha alterada. Entre novamente.');}
  if(form.id==='coupon-form'){const p={...data,value:data.type==='percent'?Math.round(Number(data.value)*100):Math.round(Number(data.value)*100),min_subtotal:Math.round(Number(data.min_subtotal)*100),max_discount:data.max_discount?Math.round(Number(data.max_discount)*100):null,max_uses:Number(data.max_uses),per_user_limit:Number(data.per_user_limit),starts_at:new Date(data.starts_at).toISOString(),ends_at:new Date(data.ends_at).toISOString(),active:true};await api('/admin/coupons',{method:'POST',body:p});closeDialog();await render();toast('Cupom criado.');}
  if(form.id==='invoice-emit-form'){const row=await api(`/admin/orders/${form.dataset.id}/invoice`,{method:'POST',body:{action:'emit',fiscal:{items:Array.from({length:Number(data.item_count)},(_,i)=>readFiscal(data,`item_${i}_`)),payment:{...JSON.parse(data.payment_extra||'{}'),forma_pagamento:data.payment_type}}}});invoiceDialog(state.invoiceOrder,row);await render();}
  if(form.id==='invoice-cancel-form'){const row=await api(`/admin/orders/${form.dataset.id}/invoice`,{method:'POST',body:{action:'cancel',reason:data.reason}});invoiceDialog(state.invoiceOrder,row);await render();}
  if(form.id==='auth-form'){const register=form.dataset.register==='true',result=await api(`/auth/${register?'register':'login'}`,{method:'POST',body:data});state.user=result.user;state.csrf=result.csrf;closeDialog();location.hash=has('dashboard')?'admin':'store';await render();toast(register?'Sua conta foi criada.':'Você entrou na sua conta.');}
  if(form.id==='checkout-form'){if(!state.quote)throw new Error('Calcule o frete antes de confirmar.');const {service_id,coupon,...address}=data;const o=await api('/checkout',{method:'POST',headers:{'Idempotency-Key':state.checkoutKey},body:{quote_id:state.quote.id,service_id,address,coupon:coupon||null}});location.hash='orders';await render();orderDialog(o);if(state.config.mode==='live'&&o.payment_url)location.assign(o.payment_url);}
  if(form.id==='category-form'||form.classList.contains('category-edit-form')){await api('/admin/categories',{method:'POST',body:{name:data.name,...(form.dataset.previous?{previous:form.dataset.previous}:{})}});await render();categoriesDialog();toast('Categoria salva.');}
  if(form.id==='product-form'){if(state.uploading)throw new Error('Aguarde o envio das fotos.');const p={...data,images:state.editPhotoIds,fiscal:readFiscal(data),price:Math.round(Number(data.price)*100),cost:Math.round(Number(data.cost)*100),active:data.active==='true'};for(const k of ['low_stock','weight','width','height','length'])p[k]=Number(data[k]);await api(`/admin/products${form.dataset.id?'/'+form.dataset.id:''}`,{method:form.dataset.id?'PUT':'POST',body:p});closeDialog();await render();toast('Produto salvo.');}
  if(form.id==='stock-form'){await api(`/admin/products/${form.dataset.id}/stock`,{method:'POST',body:{delta:Number(data.delta),reason:data.reason}});closeDialog();await render();toast('Estoque atualizado.');}
  if(form.id==='user-form'){await api(`/admin/users${form.dataset.id?'/'+form.dataset.id:''}`,{method:form.dataset.id?'PATCH':'POST',body:{...data,active:data.active==='true'}});closeDialog();await render();toast('Acesso atualizado.');}
  if(form.id==='expense-form'){await api('/admin/expenses',{method:'POST',headers:{'Idempotency-Key':state.expenseKey},body:{description:data.description,amount:Math.round(Number(data.amount)*100)}});closeDialog();await render();toast('Despesa registrada.');}
  if(form.id==='shipping-form')await afterOrderAction(await api(`/admin/orders/${form.dataset.id}/status`,{method:'POST',body:{status:'shipped',...data}}),true);
  if(form.id==='refund-form')await afterOrderAction(await api(`/admin/orders/${form.dataset.id}/refund`,{method:'POST'}),true);
  if(['label-form','label-buy-form'].includes(form.id))await afterOrderAction(await api(`/admin/orders/${form.dataset.id}/label`,{method:'POST',body:{action:form.id==='label-form'?'create':'buy',...data}}),true);
  if(form.id==='password-form'){await api('/auth/password',{method:'POST',body:data});state.user=null;state.csrf=null;state.cart={items:[],subtotal:0};location.hash='store';authDialog();await render();toast('Senha alterada. Entre novamente.');}
}catch(error){toast(error.message,true);}finally{if(btn)btn.disabled=false;}});
window.addEventListener('hashchange',()=>{if(location.hash!=='#catalog')closeDialog();render();});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
(async()=>{try{state.config=await api('/config');const auth=await api('/auth/me');state.user=auth.user;state.csrf=auth.csrf;await render();}catch(e){$('#app').innerHTML=empty('Não foi possível iniciar a loja',e.message);}})();
function photoPreview(){return(state.editPhotoIds||[]).map((id,index)=>`<div class="photo-thumb"><img src="/media/${id}.jpg" alt="Foto ${index+1}"><button type="button" data-action="remove-photo" data-index="${index}" aria-label="Remover foto ${index+1}">×</button></div>`).join('');}
document.addEventListener('change',async e=>{
  if(e.target.matches('#product-form [name=category]')){$('#product-size').innerHTML=sizeField(e.target.value);return;}
  if(e.target.id!=='product-photos')return;
  const files=[...e.target.files];if(files.length+state.editPhotoIds.length>8){toast('Use até oito fotos por produto.',true);e.target.value='';return;}
  const editor=$('#product-form'),ids=state.editPhotoIds;state.uploading=true;const submit=editor.querySelector('button[type="submit"]');submit.disabled=true;
  try{for(const file of files){if(file.size>5*1024*1024)throw new Error('Cada foto deve ter até 5 MB.');const prepared=await preparePhoto(file);const r=await fetch('/api/admin/media',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'image/jpeg','X-CSRF-Token':state.csrf},body:prepared});const result=await r.json();if(!r.ok)throw new Error(result.error);if(!editor.isConnected)return;ids.push(result.id);$('#photo-preview').innerHTML=photoPreview();}toast('Fotos enviadas. Salve o produto para aplicar.');}catch(error){toast(error.message,true);}finally{if(editor.isConnected){state.uploading=false;submit.disabled=false;}e.target.value='';}
});
function forgotDialog(){dialog('Recuperar senha',`<p>Informe o e-mail da sua conta para receber um link de recuperação.</p><form id="forgot-form">${field('email','E-mail','','email','required autocomplete="email"')}<div class="form-actions"><button class="btn primary" type="submit">Enviar link de recuperação</button></div></form>`);}
function couponsPage(rows){return adminShell('coupons',`${title('Cupons de desconto','Validade, limites e descontos calculados no servidor.','<button class="btn primary" data-action="new-coupon">+ Novo cupom</button>')}<div class="note">O desconto vale apenas para os produtos. Os usos são reservados no checkout e confirmados após pagamento. Cancelamento e expiração liberam a reserva.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Código</th><th>Desconto</th><th>Validade</th><th>Usos / reservados</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${escape(c.code)}</strong><small>${c.active?'Ativo':'Inativo'}</small></td><td>${c.type==='percent'?`${c.value/100}%`:money(c.value)}<small>Mínimo ${money(c.min_subtotal)}</small></td><td>${date(c.starts_at)}<small>Até ${date(c.ends_at)}</small></td><td>${c.used||0} / ${c.reserved||0}<small>Limite total: ${c.max_uses} · Por cliente: ${c.per_user_limit}</small></td><td><button class="btn small" data-action="toggle-coupon" data-code="${escape(c.code)}" data-active="${!c.active}">${c.active?'Desativar':'Ativar'}</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Crie seu primeiro cupom'):''}</section>`);}
function couponDialog(){const local=v=>new Date(v.getTime()-v.getTimezoneOffset()*60000).toISOString().slice(0,16);dialog('Novo cupom',`<form id="coupon-form"><div class="form-grid">${field('code','Código','','text','required minlength="3" maxlength="40" pattern="[A-Za-z0-9_-]+"')}<label class="field">Tipo<select name="type"><option value="percent">Percentual (%)</option><option value="fixed">Valor fixo (${currencyLabel()})</option></select></label>${field('value',`Desconto (% ou ${currencyLabel()})`,'','number','required min="0.01" step="0.01"')}${field('min_subtotal',`Subtotal mínimo (${currencyLabel()})`,'0','number','required min="0" step="0.01"')}${field('max_discount',`Teto de desconto (${currencyLabel()}, opcional)`,'','number','min="0.01" step="0.01"')}${field('max_uses','Limite total de usos','100','number','required min="1"')}${field('per_user_limit','Limite por cliente','1','number','required min="1"')}${field('starts_at','Início',local(new Date()),'datetime-local','required')}${field('ends_at','Fim',local(new Date(Date.now()+30*86400000)),'datetime-local','required')}</div><div class="form-actions"><button class="btn primary" type="submit">Criar cupom</button></div></form>`);}
const invoiceStatus={authorized:'Autorizada',processing:'Em processamento',submitting:'Enviando',unknown:'Consultar provedor',not_found:'Não encontrada',rejected:'Rejeitada',cancelled:'Cancelada'};
function invoiceSummary(row){if(!row)return'';return`<div class="note"><strong>NF-e ${escape(row.number||'')} · ${invoiceStatus[row.status]||row.status}</strong><p>${row.environment==='demo'?'SIMULAÇÃO · sem valor fiscal':row.environment==='homologation'?'HOMOLOGAÇÃO · sem valor fiscal':'Produção'}</p>${row.pdf_url?`<a class="btn small" href="/api/orders/${row.order_id}/invoice/pdf" target="_blank" rel="noopener">DANFE ↓</a>`:''} ${row.xml_url?`<a class="btn small" href="/api/orders/${row.order_id}/invoice/xml" target="_blank" rel="noopener">XML ↓</a>`:''}</div>`;}
function invoicesPage(rows){return adminShell('invoices',`${title('Notas fiscais','Emissão, autorização, documentos e cancelamento vinculados ao pedido.')}<div class="note">Ambiente fiscal: ${state.config.fiscal_environment==='production'?'Produção':state.config.fiscal_environment==='demo'?'Simulação sem valor fiscal':'Homologação sem valor fiscal'}. Para emitir, abra um pedido pago antes da expedição.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Nota / série</th><th>Situação</th><th>Ambiente</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>#${r.order_number}</td><td>${escape(r.customer_name)}</td><td>${escape(r.number||'—')} / ${escape(r.series||'—')}</td><td>${invoiceStatus[r.status]||r.status}</td><td>${escape(r.environment)}</td><td><button class="btn small" data-action="invoice" data-id="${r.order_id}">Gerenciar</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Nenhuma nota emitida'):''}</section>`);}
function invoiceDialog(order,row){state.invoiceOrder=order;dialog(`NF-e · Pedido #${order.number}`,`${row?invoiceSummary(row)+`<p class="muted">${escape(row.message||'')}</p><p class="form-help">Referência: ${escape(row.ref)}</p>`:'<p>A emissão seguirá os itens, o desconto e o frete registrados neste pedido.</p>'}<div class="form-actions">${!row||['rejected','not_found'].includes(row.status)?`<button class="btn primary" data-action="invoice-issue" data-id="${order.id}">Revisar e emitir NF-e</button>`:''}${row?`<button class="btn" data-action="invoice-consult" data-id="${order.id}">Consultar situação</button>`:''}${row?.status==='authorized'?`<button class="btn danger" data-action="invoice-cancel" data-id="${order.id}">Cancelar NF-e</button>`:''}</div>`);}
function invoiceIssueDialog(id,preview){dialog('Revisar emissão de NF-e',`<p>${state.config.fiscal_environment==='demo'?'Esta operação é uma simulação, sem valor fiscal.':state.config.fiscal_environment==='homologation'?'Emissão em homologação, sem valor fiscal.':'Esta operação enviará uma NF-e de produção para autorização.'}</p>${preview.error?`<p class="danger-note">${escape(preview.error)}</p>`:''}<form id="invoice-emit-form" data-id="${id}">${preview.items.map((item,index)=>`<fieldset class="fiscal-item"><legend>${escape(item.name)}</legend><div class="form-grid">${fiscalEditor(item.fiscal,`item_${index}_`)}</div></fieldset>`).join('')}<input type="hidden" name="item_count" value="${preview.items.length}">${field('payment_type','Código fiscal do meio de pagamento',preview.payment?.forma_pagamento||'','text',state.config.fiscal_environment==='demo'?'maxlength="2"':'required pattern="[0-9]{2}" maxlength="2"')}<p class="form-help">Confira o meio efetivamente recebido (ex.: 03 crédito, 04 débito, 15 boleto, 17 PIX dinâmico, 18 carteira digital).</p><label class="field">Dados complementares do pagamento (avançado)<textarea name="payment_extra" class="code-field">${escape(JSON.stringify(Object.fromEntries(Object.entries(preview.payment||{}).filter(([k])=>!['forma_pagamento','valor_pagamento'].includes(k))),null,2))}</textarea></label><p class="form-help">Revise NCM, CFOP e tributos com o responsável contábil. Quantidades, preços, desconto e frete vêm do pedido.</p>${preview.payload&&!preview.payload.demo?`<details><summary>Conferir dados completos da nota</summary><pre>${escape(JSON.stringify(preview.payload,null,2))}</pre></details>`:''}<div class="form-actions"><button class="btn primary" type="submit">Confirmar emissão</button></div></form>`);}
function emailsPage(rows){return adminShell('emails',`${title('E-mails de recuperação','Acompanhe a fila e as tentativas de envio.')}<div class="note">${state.config.mode==='demo'?'Na demonstração, as mensagens aparecem aqui e não são enviadas.':'Mensagens são processadas a cada minuto, com até cinco tentativas. Conteúdo e links não são exibidos em produção.'}</div><section class="panel">${rows.length?rows.map(r=>`<article class="email-row"><strong>${escape(r.subject)}</strong><p class="muted">${escape(r.recipient)} · ${r.sent_at?'Enviado':r.attempts>=5?'Falha definitiva':'Na fila'} · Tentativas: ${r.attempts}</p>${r.last_error?`<p class="danger-note">${escape(r.last_error)}</p>`:''}${r.preview?`<pre>${escape(r.preview)}</pre>`:''}</article>`).join(''):empty('Nenhum e-mail na fila')}</section>`);}
const fiscalInputs=[['codigo_ncm','NCM (8 dígitos)'],['cfop','CFOP (4 dígitos)'],['unidade_comercial','Unidade comercial'],['icms_origem','Origem da mercadoria'],['icms_situacao_tributaria','Situação tributária ICMS / CSOSN'],['pis_situacao_tributaria','Situação tributária PIS'],['cofins_situacao_tributaria','Situação tributária COFINS']];
function fiscalEditor(f,prefix=''){const extras=Object.fromEntries(Object.entries(f).filter(([k])=>!fiscalInputs.some(([key])=>key===k)));return`<div class="field full"><strong>Dados fiscais</strong><span class="muted">Configure conforme orientação contábil.</span></div>${fiscalInputs.map(([key,label])=>field(prefix+key,label,f[key]??'','text',key==='codigo_ncm'?'maxlength="8"':key==='cfop'?'maxlength="4"':'')).join('')}<label class="field full">Campos tributários adicionais (avançado)<textarea name="${prefix}fiscal_extra" class="code-field">${escape(JSON.stringify(extras,null,2))}</textarea></label>`;}
function readFiscal(data,prefix=''){const value=JSON.parse(data[prefix+'fiscal_extra']||'{}');for(const [key] of fiscalInputs){const input=data[prefix+key];if(input?.trim())value[key]=input.trim();else delete value[key];}return value;}

async function preparePhoto(file){
  const bitmap=await createImageBitmap(file);
  try{const scale=Math.min(1,1280/bitmap.width,1280/bitmap.height),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext("2d");context.fillStyle="#ffffff";context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);return await new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error("Imagem inválida.")),"image/jpeg",0.85));}finally{bitmap.close();}
}
